function d_ideate(P,R){var n=P.n||6,out=[];for(var i=0;i<n;i++){var nov=+(0.3+0.7*R()).toFixed(3),fea=+(0.3+0.7*R()).toFixed(3);out.push({id:'IDEA-'+(i+1),novelty:nov,feasibility:fea,score:+(0.6*nov+0.4*fea).toFixed(3)});}out.sort(function(a,b){return b.score-a.score;});return{objective:P.objective||'invention',candidates:out.slice(0,3),evaluated:n};}

// invoked with params:
// {"n":6,"objective":"capability objective"}

function d_team_vote(P,R){var ideas=P.ideas||['A','B','C','D'],voters=P.voters||9,scores={};ideas.forEach(function(id){scores[id]=0;});for(var v=0;v<voters;v++){var order=ideas.slice().sort(function(){return R()-0.5;});order.forEach(function(id,r){scores[id]+=ideas.length-r;});}var rank=ideas.map(function(id){return{id:id,points:scores[id]};}).sort(function(a,b){return b.points-a.points;});return{voters:voters,ranking:rank,winner:rank[0].id};}

